// Проверяем, является ли файл юридическим документом
const fileName = ($('получаем данные о файлах').item.json.name || '').toLowerCase();
const fileType = $('получаем данные о файлах').item.json.type;

// Ключевые слова для определения юридических документов
const legalKeywords = [
  'договор', 'contract', 'соглашение', 'agreement',
  'нда', 'nda', 'аренда', 'rental', 'lease',
  'услуг', 'service', 'трудов', 'employment',
  'купли', 'purchase', 'продаж', 'sale'
];

const isLegalDoc = legalKeywords.some(keyword => fileName.includes(keyword));
const isPdfOrDocx = fileType === 'pdf' || fileType === 'document';

return [{
  json: {
    isLegalDocument: isLegalDoc && isPdfOrDocx,
    fileName: fileName,
    fileType: fileType,
    shouldAnalyze: isLegalDoc && isPdfOrDocx
  }
}];
